using System;
using System.Linq;
using System.Globalization;
namespace IdleIntelligence.Core
{
 [Serializable]public sealed class CommerceRewardTicket{public string id,kind,context,job="";public double expiresAt;public NumberData amount;public CommerceRewardTicket Copy(){var t=(CommerceRewardTicket)MemberwiseClone();t.amount=ScientificNumber.FromData(amount).ToData();return t;}}
 [Serializable]public sealed class AdState
 {public int schema=1;public bool initialized,hasPending;public long day,gemVideos;public double gemNextAt,droneNextAt,creditBoostUntil;public int[] counts=new int[3],legacyCounts=new int[3];public CommerceRewardTicket pending;public static AdState New()=>new AdState{initialized=true};public AdState Copy(){var a=(AdState)MemberwiseClone();a.counts=(int[])counts.Clone();a.legacyCounts=(int[])legacyCounts.Clone();a.pending=hasPending?pending?.Copy():null;return a;}}
 public sealed class ResearchSkipQuote{public string Job;public double Seconds;public long Cost;public bool Allowed;}
 public sealed class AdQuote{public ScientificNumber Amount;public long Day;public int Remaining;public double Cooldown;public string Job;public bool Allowed;}
 public static class AdRewards
 {
  const long Max=9007199254740991L;
  public static string Context(GameState s)=>"["+Market.Json(s.Missions.campaign)+","+s.Prestige.resets.ToString(CultureInfo.InvariantCulture)+","+s.Meta.resets.ToString(CultureInfo.InvariantCulture)+"]";
  public static void MigrateJobs(GameState s){if(s.Prestige?.labs==null)return;int index=0;foreach(var job in new[]{s.ResearchJob}.Concat(s.Prestige.labs)){if(job!=null&&!job.identityRecorded){job.identityRecorded=true;job.slot=index;job.key="legacy-research-"+index+"-"+job.id+"-"+job.required.ToString("R",CultureInfo.InvariantCulture);}index++;}}
  public static int FreeLab(GameState s)=>Enumerable.Range(0,PrestigeAutomation.LabCount(s)).Where(i=>!PrestigeAutomation.ResearchJobs(s).Any(j=>j.slot==i)).DefaultIfEmpty(-1).First();
  public static ResearchSkipQuote SkipQuote(GameState s,int index){var j=PrestigeAutomation.ResearchJobs(s).FirstOrDefault(job=>job.slot==index);double seconds=j==null?0:Math.Max(0,j.required-j.done)/Game.ResearchSpeed(s,j);double cost=Math.Ceiling(seconds/60*AdBalance.ResearchPerMinute);return new ResearchSkipQuote{Job=j?.key??"",Seconds=seconds,Cost=cost>Max?Max+1:(long)cost,Allowed=!ChallengeRules.Active(s)&&seconds>0};}
  static GameState Skip(GameState state,string key,double seconds){var s=state.Copy();var j=PrestigeAutomation.ResearchJobs(s).FirstOrDefault(job=>job.key==key);if(j==null)return state;double work=Math.Min(j.required-j.done,seconds*Game.ResearchSpeed(s,j));if(work<=0)return state;j.done+=work;Game.SettleResearch(s);return PrestigeAutomation.StartResearchQueue(s);}
  public static GameState BuySkip(GameState s,int index,string job,long cost){var q=SkipQuote(s,index);if(!q.Allowed||q.Job!=job||q.Cost!=cost||cost>Max||s.Retention.gems<cost)return s;var n=Skip(s,job,q.Seconds);if(ReferenceEquals(n,s))return s;string id="research:"+job;RetentionRules.Gems(n,-cost,id,"research-skip");n.Commerce.hasLast=true;n.Commerce.last=new CommerceReceipt{id=id,kind="research",amount=Math.Ceiling(q.Seconds).ToString(CultureInfo.InvariantCulture)+" s"};LocalJournal.Record(n,"gem-purchase",job);return n;}
  public static AdQuote Quote(GameState s,string kind,int index=0){int i=Array.IndexOf(AdBalance.Kinds,kind);if(i<0)return new AdQuote{Amount=ScientificNumber.Zero};var a=s.Ads;long day=Math.Max(a.day,(long)Math.Floor(s.SavedAt/AdBalance.CycleMs));int count=day==a.day?a.counts[i]:0;var lab=SkipQuote(s,index);var amount=kind=="gems"?ScientificNumber.From(AdBalance.RewardGems*((a.gemVideos+1)%AdBalance.DroneEvery==0?AdBalance.DroneMultiplier:1)):kind=="creditDrop"?Game.Income(s,false).Times(AdBalance.DroneSeconds):ScientificNumber.From(Math.Min(lab.Seconds,AdBalance.ResearchSeconds));double cooldown=kind=="gems"?Math.Max(0,a.gemNextAt-s.SavedAt):kind=="creditDrop"?Math.Max(0,a.droneNextAt-s.SavedAt):0;return new AdQuote{Day=day,Amount=amount,Remaining=Math.Max(0,AdBalance.Limits[i]-count),Cooldown=cooldown,Job=kind=="research"?lab.Job:"",Allowed=!ChallengeRules.Active(s)&&count<AdBalance.Limits[i]&&(kind!="gems"||a.gemVideos<Max)&&cooldown==0&&!amount.IsZero&&(kind!="research"||lab.Allowed)};}
  public static GameState Begin(GameState s,string kind,string tx,int index=0,string expectedJob=null){var q=Quote(s,kind,index);if(expectedJob!=null&&expectedJob!=q.Job||string.IsNullOrEmpty(tx)||tx.Length>160||s.Rewards.transactions.Contains(tx)||s.Ads.hasPending&&s.Ads.pending.context==Context(s)&&s.Ads.pending.expiresAt>s.SavedAt||!q.Allowed)return s;var n=s.Copy();n.Ads.hasPending=true;n.Ads.pending=new CommerceRewardTicket{id=tx,kind=kind,job=q.Job,context=Context(s),expiresAt=s.SavedAt+AdBalance.TicketMs,amount=q.Amount.ToData()};return n;}
  public static GameState Cancel(GameState s,string tx){if(!s.Ads.hasPending||s.Ads.pending.id!=tx)return s;var n=s.Copy();n.Ads.hasPending=false;n.Ads.pending=null;return n;}
  static string Scientific(ScientificNumber n){if(n.IsZero)return "0";double m=Math.Round(n.Mantissa,2,MidpointRounding.AwayFromZero);return m.ToString(m>=10?"F1":"F2",CultureInfo.InvariantCulture)+"e"+(n.Exponent>=0?"+":"")+n.Exponent.ToString(CultureInfo.InvariantCulture);}
  public static int LegacyRemaining(GameState s,string kind){int i=Array.IndexOf(AdBalance.LegacyKinds,kind);return i<0?0:Math.Max(0,AdBalance.LegacyLimits[i]-(s.Capsules.day==MissionCalendar.Key(s.SavedAt,0)?s.Ads.legacyCounts[i]:0));}
  public static GameState BeginLegacy(GameState s,string kind,string tx){if(!new[]{"creditBoost","components"}.Contains(kind)||ChallengeRules.Active(s)||kind=="components"&&s.Prestige.resets<1||LegacyRemaining(s,kind)<=0||string.IsNullOrEmpty(tx)||tx.Length>160||s.Capsules.videoTransactions.Contains(tx)||s.Ads.hasPending)return s;var n=s.Copy();n.Ads.hasPending=true;n.Ads.pending=new CommerceRewardTicket{id=tx,kind=kind,job="",context=Context(s),expiresAt=s.SavedAt+AdBalance.TicketMs,amount=ScientificNumber.Zero.ToData()};return n;}
  public static GameState ClaimAdFree(GameState s,string tx)=>PurchaseRules.AdFree(s)?Complete(s,tx,"success"):Cancel(s,tx);
  public static GameState Complete(GameState s,string tx,string result){var t=s.Ads.hasPending?s.Ads.pending:null;if(t==null||t.id!=tx)return s;var n=Cancel(s,tx);if(result!="success"||ChallengeRules.Active(s)||t.context!=Context(s)||s.SavedAt>t.expiresAt||s.Rewards.transactions.Contains(tx))return n;if(AdBalance.LegacyKinds.Contains(t.kind)&&t.kind!="creditDrop")return Legacy(n,t.kind,tx,result,s.SavedAt);int index=t.job==""?0:PrestigeAutomation.ResearchJobs(s).FirstOrDefault(j=>j.key==t.job)?.slot??-1;var q=Quote(n,t.kind,index);if(!q.Allowed)return n;var value=ScientificNumber.FromData(t.amount);if(t.kind=="research"){var skipped=Skip(n,t.job,Math.Min(value.ToDouble(),q.Amount.ToDouble()));if(ReferenceEquals(skipped,n))return n;n=skipped;}else if(t.kind=="creditDrop")n.Credits=n.Credits.Add(value);else{double amount=value.ToDouble();if(amount>Max||amount!=Math.Floor(amount)||n.Retention.gems>Max-amount)return n;RetentionRules.Gems(n,(long)amount,tx,"rewarded-gems");}var a=n.Ads;if(q.Day!=a.day)a.counts=new int[3];a.day=q.Day;a.counts[Array.IndexOf(AdBalance.Kinds,t.kind)]++;if(t.kind=="gems"){a.gemVideos++;a.gemNextAt=s.SavedAt+AdBalance.GemCooldown;}if(t.kind=="creditDrop")a.droneNextAt=s.SavedAt+AdBalance.DroneCooldown;n.Rewards.transactions=n.Rewards.transactions.Concat(new[]{tx}).ToArray();n.Commerce.hasLast=true;n.Commerce.last=new CommerceReceipt{id=tx,kind=t.kind,amount=Scientific(value)};LocalJournal.Record(n,"ad-reward",tx);return n;}
  // Existing legacy API; production UI never fabricates a successful provider response.
  public static GameState Legacy(GameState s,string kind,string tx,string result,double now){int i=Array.IndexOf(AdBalance.LegacyKinds,kind);if(ChallengeRules.Active(s)||i<0||result!="success"||s.Capsules.videoTransactions.Contains(tx)||kind=="components"&&s.Prestige.resets<1)return s;string day=MissionCalendar.Key(now,0);int used=s.Capsules.day==day?s.Ads.legacyCounts[i]:0;if(used>=AdBalance.LegacyLimits[i])return s;var n=s.Copy();if(n.Capsules.day!=day){n.Ads.legacyCounts=new int[3];n.Capsules.videos=0;}n.Capsules.day=day;n.Ads.legacyCounts[i]=used+1;n.Capsules.videoTransactions=n.Capsules.videoTransactions.Concat(new[]{tx}).ToArray();if(kind=="creditBoost")n.Ads.creditBoostUntil=Math.Max(now,n.Ads.creditBoostUntil)+AdBalance.CreditBoostMs;if(kind=="components"){n.Workshop.components[0]+=(long)AdBalance.Components;Lifetime.Components(n,0,(long)AdBalance.Components);LocalJournal.Record(n,"component-found",tx);}if(kind=="creditDrop")n.Credits=n.Credits.Add(Game.Income(n,false).Times(AdBalance.DroneSeconds));return n;}
  public static void Validate(GameState s){if(s.Prestige?.labs==null)throw new FormatException("Missing prestige research state");var a=s.Ads;if(a==null||!a.initialized||a.schema!=1||a.day<0||a.gemVideos<0||a.gemVideos>Max||a.counts==null||a.counts.Length!=3||a.legacyCounts==null||a.legacyCounts.Length!=3||a.counts.Where((n,i)=>n<0||n>AdBalance.Limits[i]).Any()||a.legacyCounts.Where((n,i)=>n<0||n>AdBalance.LegacyLimits[i]).Any()||new[]{a.gemNextAt,a.droneNextAt,a.creditBoostUntil}.Any(t=>!ScientificNumber.Finite(t)||t<0||t>Max))throw new FormatException("Invalid ad state");if(a.hasPending){var t=a.pending;if(t==null||string.IsNullOrEmpty(t.id)||t.id.Length>160||!AdBalance.Kinds.Contains(t.kind)&&!new[]{"creditBoost","components"}.Contains(t.kind)||t.context==null||t.job==null||!ScientificNumber.Finite(t.expiresAt)||t.expiresAt<0||t.expiresAt>Max)throw new FormatException("Invalid ad ticket");ScientificNumber.FromData(t.amount);}var jobs=PrestigeAutomation.ResearchJobs(s).ToArray();if(jobs.Any(j=>!j.identityRecorded||string.IsNullOrEmpty(j.key)||j.slot<0||j.slot>=GemBalance.MaximumLabs)||jobs.Select(j=>j.slot).Distinct().Count()!=jobs.Length||jobs.Select(j=>j.key).Distinct().Count()!=jobs.Length)throw new FormatException("Invalid research identities");}
 }
}
